"use client";

import { FormEvent, useMemo, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import ListToolbar, { exportCsv, paginate } from "@/components/ListToolbar";

export type OperationProfile = { id:string; full_name:string|null; email:string|null; role:string; status:string };
export type ProjectRow = { id:string; code:string; name:string; description:string|null; program_id:string|null; status:string; location:string|null; start_date:string|null; end_date:string|null; budget_amount:number|null; budget_currency:string; created_by:string; updated_at:string };
export type ProjectProgramRow = { id:string; code:string; name:string; description:string|null; thematic_area:string|null; manager_id:string|null; status:string; start_date:string|null; end_date:string|null; budget_amount:number|null; budget_currency:string; created_by:string; created_at:string; updated_at:string };
export type PortfolioActivityRow = { id:string; code:string; title:string; activity_type:string; description:string|null; program_id:string|null; project_id:string|null; location:string|null; starts_at:string; ends_at:string|null; status:string; expected_participants:number|null; actual_participants:number|null; budget_amount:number|null; budget_currency:string; manager_id:string|null; created_by:string; created_at:string; updated_at:string };
export type ProjectMemberRow = { project_id:string; user_id:string; member_role:string; joined_at:string };
export type TaskRow = { id:string; title:string; description:string|null; request_id:string|null; project_id:string|null; created_by:string; assigned_to:string|null; status:string; priority:string; due_at:string|null; completed_at:string|null; created_at:string; updated_at?:string };
export type DocumentRow = { id:string; owner_id:string; request_id:string|null; project_id:string|null; title:string; file_url:string; file_name:string|null; mime_type:string|null; size_bytes:number|null; visibility:string; created_at:string };
export type BeneficiaryRow = { id:string; reference_code:string; project_id:string; full_name:string; gender:string; birth_date:string|null; phone:string|null; locality:string|null; support_notes:string|null; consent_at:string|null; status:string; assigned_to:string|null; created_at:string };
export type OperationalRequest = { id:string; subject:string; description:string; request_type:string; status:string; priority:string; created_at:string; updated_at?:string; created_by?:string; assigned_to?:string|null; project_id?:string|null; body_id?:string|null; region?:string|null; due_at?:string|null; first_responded_at?:string|null; resolved_at?:string|null; closed_at?:string|null; archived_at?:string|null; archived_by?:string|null; archive_reason?:string|null; reopened_count?:number; last_reopened_at?:string|null; last_reopened_by?:string|null };
export type WorkflowEvent = { id:string; actor_id:string|null; event_type:string; body:string|null; from_value:string|null; to_value:string|null; visibility?:string; metadata?:Record<string,unknown>; created_at:string; request_id?:string; task_id?:string };
export type InterventionRow={id:string;case_number:string;request_id:string;body_id:string|null;project_id:string|null;region:string|null;assigned_to:string|null;title:string;summary:string|null;priority:string;sensitivity:string;status:string;due_at:string|null;opened_at:string;resolved_at:string|null;closed_at:string|null;archived_at:string|null;created_by:string;created_at:string;updated_at:string};
export type OperationBody={id:string;code:string;name:string;body_type:string;deployment_level:string;region:string|null;locality:string|null;status:string};

const projectStatus:Record<string,string>={planned:"Planifié",active:"Actif",on_hold:"En pause",completed:"Terminé",cancelled:"Annulé"};
const taskStatus:Record<string,string>={todo:"À faire",in_progress:"En cours",blocked:"Bloquée",done:"Terminée",cancelled:"Annulée"};
const activityStatus:Record<string,string>={planned:"Planifiée",confirmed:"Confirmée",in_progress:"En cours",completed:"Terminée",cancelled:"Annulée",postponed:"Reportée"};
export const requestStatus:Record<string,string>={new:"Nouvelle",under_review:"À examiner",assigned:"Affectée",in_progress:"En cours",waiting_user:"En attente du demandeur",resolved:"Résolue",closed:"Clôturée",rejected:"Rejetée"};
const priorities:Record<string,string>={low:"Faible",normal:"Normale",high:"Élevée",urgent:"Urgente"};
const eventLabels:Record<string,string>={comment:"Commentaire",status_change:"Statut modifié",assignment:"Affectation modifiée",priority_change:"Priorité modifiée",project_change:"Projet modifié",due_date_change:"Échéance modifiée",routing_change:"Rattachement modifié",information_request:"Informations complémentaires demandées",intervention_created:"Dossier d’intervention créé",archived:"Demande archivée",unarchived:"Demande désarchivée",reopened:"Demande rouverte"};

function options(values:Record<string,string>){return Object.entries(values).map(([value,label])=>({value,label}));}

export default function OperationsPanel({
  profile, initialProjects, initialPrograms, initialActivities, initialMembers, initialTasks, initialDocuments, initialBeneficiaries,
  initialRequests, initialRequestEvents, initialTaskEvents, initialInterventions, staffProfiles, bodies
}:{
  profile:OperationProfile; initialProjects:ProjectRow[]; initialPrograms:ProjectProgramRow[]; initialActivities:PortfolioActivityRow[]; initialMembers:ProjectMemberRow[]; initialTasks:TaskRow[];
  initialDocuments:DocumentRow[]; initialBeneficiaries:BeneficiaryRow[]; initialRequests:OperationalRequest[];
  initialRequestEvents:WorkflowEvent[]; initialTaskEvents:WorkflowEvent[]; initialInterventions:InterventionRow[]; staffProfiles:OperationProfile[]; bodies:OperationBody[];
}) {
  const supabase=useMemo(()=>createClient(),[]);
  const [view,setView]=useState("pilotage");
  const [projects,setProjects]=useState(initialProjects);
  const [programs,setPrograms]=useState(initialPrograms);
  const [activities,setActivities]=useState(initialActivities);
  const [members,setMembers]=useState(initialMembers);
  const [tasks,setTasks]=useState(initialTasks);
  const [documents,setDocuments]=useState(initialDocuments);
  const [beneficiaries,setBeneficiaries]=useState(initialBeneficiaries);
  const [requests,setRequests]=useState(initialRequests);
  const [requestEvents,setRequestEvents]=useState(initialRequestEvents);
  const [interventions,setInterventions]=useState(initialInterventions);
  const [taskEvents,setTaskEvents]=useState(initialTaskEvents);
  const [query,setQuery]=useState("");
  const [filterStatus,setFilterStatus]=useState("all");
  const [page,setPage]=useState(1);
  const [requestRegion,setRequestRegion]=useState("all");
  const [requestFrom,setRequestFrom]=useState("");
  const [requestTo,setRequestTo]=useState("");
  const [archiveFilter,setArchiveFilter]=useState("active");
  const [notice,setNotice]=useState("");
  const [busy,setBusy]=useState(false);
  const isAdmin=["admin","super_admin"].includes(profile.role);
  const profileNames=useMemo(()=>Object.fromEntries(staffProfiles.map(item=>[item.id,item.full_name||item.email||"Compte AIAC"])),[staffProfiles]);
  const projectNames=useMemo(()=>Object.fromEntries(projects.map(item=>[item.id,item.name])),[projects]);
  const bodyNames=useMemo(()=>Object.fromEntries(bodies.map(item=>[item.id,`${item.code} · ${item.name}`])),[bodies]);
  const programNames=useMemo(()=>Object.fromEntries(programs.map(item=>[item.id,item.name])),[programs]);
  const activeStaff=staffProfiles.filter(item=>item.status==="active"&&["staff","manager","admin","super_admin"].includes(item.role));
  const activeCollaborators=staffProfiles.filter(item=>item.status==="active"&&["volunteer","staff","manager","partner","admin","super_admin"].includes(item.role));
  const managedProjectIds=new Set(members.filter(item=>item.user_id===profile.id&&item.member_role==="lead").map(item=>item.project_id));
  const manageableProjects=isAdmin?projects:projects.filter(item=>managedProjectIds.has(item.id));
  const writableProjectIds=new Set(members.filter(item=>item.user_id===profile.id&&item.member_role!=="viewer").map(item=>item.project_id));
  const writableProjects=isAdmin?projects:projects.filter(item=>writableProjectIds.has(item.id));

  const q=query.toLowerCase();
  const filteredProjects=projects.filter(item=>`${item.code} ${item.name} ${item.description||""} ${item.location||""}`.toLowerCase().includes(q)&&(filterStatus==="all"||item.status===filterStatus));
  const filteredRequests=requests.filter(item=>`${item.subject} ${item.description} ${item.request_type} ${projectNames[item.project_id||""]||""} ${bodyNames[item.body_id||""]||""} ${item.region||""}`.toLowerCase().includes(q)&&(filterStatus==="all"||item.status===filterStatus)&&(requestRegion==="all"||item.region===requestRegion)&&(!requestFrom||item.created_at>=`${requestFrom}T00:00:00`)&&(!requestTo||item.created_at<=`${requestTo}T23:59:59.999`)&&(archiveFilter==="all"||(archiveFilter==="archived"?Boolean(item.archived_at):!item.archived_at)));
  const filteredTasks=tasks.filter(item=>`${item.title} ${item.description||""} ${projectNames[item.project_id||""]||""} ${profileNames[item.assigned_to||""]||""}`.toLowerCase().includes(q)&&(filterStatus==="all"||item.status===filterStatus));
  const filteredBeneficiaries=beneficiaries.filter(item=>`${item.reference_code} ${item.full_name} ${item.locality||""} ${projectNames[item.project_id]||""}`.toLowerCase().includes(q)&&(filterStatus==="all"||item.status===filterStatus));
  const filteredDocuments=documents.filter(item=>`${item.title} ${item.file_name||""} ${projectNames[item.project_id||""]||""} ${item.mime_type||""}`.toLowerCase().includes(q)&&(filterStatus==="all"||item.visibility===filterStatus));

  function showError(message:string){setNotice(message);setBusy(false);}
  function switchView(next:string){setView(next);setQuery("");setFilterStatus("all");setPage(1);}
  function toolbar(items:unknown[],statuses:Record<string,string>,exporter:()=>void,placeholder:string){const result=paginate(items,page);return <ListToolbar query={query} onQuery={setQuery} status={filterStatus} onStatus={setFilterStatus} options={options(statuses)} count={items.length} page={result.page} pages={result.pages} onPage={setPage} onExport={exporter} placeholder={placeholder}/>;}

  async function createProject(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);
    const programId=String(data.get("program_id")||"");if(!programId){showError("Choisissez d’abord le programme auquel appartient ce projet.");return;}
    const payload={code:String(data.get("code")||"").trim().toUpperCase().replace(/[^A-Z0-9_-]/g,"-"),name:String(data.get("name")||"").trim(),description:String(data.get("description")||"").trim()||null,program_id:programId,location:String(data.get("location")||"").trim()||null,start_date:data.get("start_date")||null,end_date:data.get("end_date")||null,budget_amount:data.get("budget_amount")?Number(data.get("budget_amount")):null,budget_currency:"XAF",created_by:profile.id};
    const {data:created,error}=await supabase.from("projects").insert(payload).select().single();
    if(error||!created){showError(error?.message||"Création impossible");return;}
    const member=await supabase.from("project_members").insert({project_id:created.id,user_id:profile.id,member_role:"lead",added_by:profile.id}).select().single();
    setProjects([created as ProjectRow,...projects]);if(member.data)setMembers([...members,member.data as ProjectMemberRow]);form.reset();setNotice("Projet créé et ajouté au portefeuille AIAC.");setBusy(false);
  }

  async function createProgram(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);
    const payload={code:String(data.get("code")||"").trim().toUpperCase().replace(/[^A-Z0-9_-]/g,"-"),name:String(data.get("name")||"").trim(),description:String(data.get("description")||"").trim()||null,thematic_area:String(data.get("thematic_area")||"").trim()||null,manager_id:String(data.get("manager_id")||"")||null,start_date:data.get("start_date")||null,end_date:data.get("end_date")||null,budget_amount:data.get("budget_amount")?Number(data.get("budget_amount")):null,budget_currency:"XAF",created_by:profile.id};
    const {data:created,error}=await supabase.from("programs").insert(payload).select().single();
    if(error||!created){showError(error?.message||"Création impossible");return;}setPrograms([created as ProjectProgramRow,...programs]);form.reset();setNotice("Programme créé. Vous pouvez maintenant y rattacher un projet.");setBusy(false);
  }

  async function createActivity(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);const projectId=String(data.get("project_id")||"");const parent=projects.find(item=>item.id===projectId);
    if(!parent?.program_id){showError("Choisissez un projet rattaché à un programme.");return;}
    const payload={title:String(data.get("title")||"").trim(),activity_type:String(data.get("activity_type")||"other"),description:String(data.get("description")||"").trim()||null,project_id:projectId,program_id:parent.program_id,location:String(data.get("location")||"").trim()||null,starts_at:new Date(String(data.get("starts_at"))).toISOString(),ends_at:data.get("ends_at")?new Date(String(data.get("ends_at"))).toISOString():null,expected_participants:data.get("expected_participants")?Number(data.get("expected_participants")):null,budget_amount:data.get("budget_amount")?Number(data.get("budget_amount")):null,budget_currency:"XAF",manager_id:String(data.get("manager_id")||"")||profile.id,created_by:profile.id};
    const {data:created,error}=await supabase.from("activities").insert(payload).select().single();
    if(error||!created){showError(error?.message||"Création impossible");return;}setActivities([created as PortfolioActivityRow,...activities]);form.reset();setNotice("Activité créée dans le projet sélectionné.");setBusy(false);
  }

  async function addMember(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);
    const {data:created,error}=await supabase.from("project_members").insert({project_id:String(data.get("project_id")),user_id:String(data.get("user_id")),member_role:String(data.get("member_role")),added_by:profile.id}).select().single();
    if(error||!created){showError(error?.message||"Ajout impossible");return;}setMembers([...members,created as ProjectMemberRow]);form.reset();setNotice("Membre ajouté à l’équipe du projet.");setBusy(false);
  }

  async function createTask(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);
    const payload={title:String(data.get("title")||"").trim(),description:String(data.get("description")||"").trim()||null,project_id:String(data.get("project_id")||"")||null,request_id:String(data.get("request_id")||"")||null,assigned_to:String(data.get("assigned_to")||"")||null,priority:String(data.get("priority")||"normal"),due_at:data.get("due_at")?new Date(String(data.get("due_at"))).toISOString():null,created_by:profile.id};
    const {data:created,error}=await supabase.from("tasks").insert(payload).select().single();
    if(error||!created){showError(error?.message||"Création impossible");return;}setTasks([created as TaskRow,...tasks]);form.reset();setNotice("Tâche créée et notification envoyée au responsable.");setBusy(false);
  }

  async function updateTask(event:FormEvent<HTMLFormElement>,task:TaskRow,canManage:boolean){
    event.preventDefault();setBusy(true);const data=new FormData(event.currentTarget);
    const payload=canManage?{title:String(data.get("title")||task.title).trim(),description:String(data.get("description")||"").trim()||null,status:String(data.get("status")),priority:String(data.get("priority")),assigned_to:String(data.get("assigned_to")||"")||null,project_id:String(data.get("project_id")||"")||null,request_id:String(data.get("request_id")||"")||null,due_at:data.get("due_at")?new Date(String(data.get("due_at"))).toISOString():null}:{status:String(data.get("status"))};
    const {data:updated,error}=await supabase.from("tasks").update(payload).eq("id",task.id).select().single();
    if(error||!updated){showError(error?.message||"Mise à jour impossible");return;}setTasks(tasks.map(item=>item.id===task.id?updated as TaskRow:item));setNotice("Tâche mise à jour et historique enregistré.");setBusy(false);
  }

  async function updateRequest(event:FormEvent<HTMLFormElement>,request:OperationalRequest){
    event.preventDefault();setBusy(true);const data=new FormData(event.currentTarget);
    const payload={status:String(data.get("status")??request.status),priority:String(data.get("priority")??request.priority),assigned_to:data.has("assigned_to")?(String(data.get("assigned_to")||"")||null):(request.assigned_to||null),project_id:data.has("project_id")?(String(data.get("project_id")||"")||null):(request.project_id||null),body_id:data.has("body_id")?(String(data.get("body_id")||"")||null):(request.body_id||null),region:data.has("region")?(String(data.get("region")||"").trim()||null):(request.region||null),due_at:data.has("due_at")&&data.get("due_at")?new Date(String(data.get("due_at"))).toISOString():null};
    const {data:updated,error}=await supabase.from("requests").update(payload).eq("id",request.id).select().single();
    if(error||!updated){showError(error?.message||"Mise à jour impossible");return;}setRequests(requests.map(item=>item.id===request.id?updated as OperationalRequest:item));setNotice("Demande traitée, notifications et historique mis à jour.");setBusy(false);
  }

  async function addComment(event:FormEvent<HTMLFormElement>,kind:"request"|"task",id:string){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const formData=new FormData(form);const body=String(formData.get("body")||"").trim();
    const table=kind==="request"?"request_events":"task_events";const key=kind==="request"?"request_id":"task_id";
    const {data:created,error}=await supabase.from(table).insert({[key]:id,actor_id:profile.id,event_type:"comment",body,...(kind==="request"?{visibility:String(formData.get("visibility")||"internal")}:{})}).select().single();
    if(error||!created){showError(error?.message||"Commentaire impossible");return;}
    if(kind==="request")setRequestEvents([created as WorkflowEvent,...requestEvents]);else setTaskEvents([created as WorkflowEvent,...taskEvents]);
    form.reset();setNotice("Commentaire ajouté au dossier.");setBusy(false);
  }

  async function requestInformation(event:FormEvent<HTMLFormElement>,request:OperationalRequest){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);const due=data.get("response_due_at")?new Date(String(data.get("response_due_at"))).toISOString():null;
    const {error}=await supabase.rpc("request_more_information",{target_id:request.id,message:String(data.get("message")||"").trim(),response_due_at:due});
    if(error){showError(error.message);return;}const now=new Date().toISOString();setRequests(rows=>rows.map(row=>row.id===request.id?{...row,status:"waiting_user",due_at:due||row.due_at}:row));setRequestEvents(rows=>[{id:crypto.randomUUID(),request_id:request.id,actor_id:profile.id,event_type:"information_request",body:String(data.get("message")||"").trim(),from_value:null,to_value:null,visibility:"requester",created_at:now},...rows]);form.reset();setNotice("La demande d’informations complémentaires a été envoyée et tracée.");setBusy(false);
  }

  async function convertToIntervention(event:FormEvent<HTMLFormElement>,request:OperationalRequest){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);
    const args={target_id:request.id,target_body_id:String(data.get("body_id")||"")||null,target_project_id:String(data.get("project_id")||"")||null,target_assigned_to:String(data.get("assigned_to")||"")||null,target_region:String(data.get("region")||"").trim()||null,target_due_at:data.get("due_at")?new Date(String(data.get("due_at"))).toISOString():null,target_sensitivity:String(data.get("sensitivity")||"standard")};
    const {data:id,error}=await supabase.rpc("convert_request_to_intervention",args);
    if(error){showError(error.message);return;}const created:InterventionRow={id:String(id),case_number:"Nouveau dossier",request_id:request.id,body_id:args.target_body_id,project_id:args.target_project_id,region:args.target_region,assigned_to:args.target_assigned_to,title:request.subject,summary:request.description,priority:request.priority,sensitivity:args.target_sensitivity,status:"open",due_at:args.target_due_at,opened_at:new Date().toISOString(),resolved_at:null,closed_at:null,archived_at:null,created_by:profile.id,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};setInterventions(rows=>[created,...rows]);setRequests(rows=>rows.map(row=>row.id===request.id?{...row,status:"in_progress",body_id:args.target_body_id||row.body_id,project_id:args.target_project_id||row.project_id,assigned_to:args.target_assigned_to||row.assigned_to,region:args.target_region||row.region,due_at:args.target_due_at||row.due_at}:row));form.reset();setNotice("La demande a été convertie en dossier d’intervention.");setBusy(false);
  }

  async function archiveRequest(event:FormEvent<HTMLFormElement>,request:OperationalRequest){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const reason=String(new FormData(form).get("reason")||"").trim();const {error}=await supabase.rpc("archive_request",{target_id:request.id,reason});
    if(error){showError(error.message);return;}setRequests(rows=>rows.map(row=>row.id===request.id?{...row,archived_at:new Date().toISOString(),archived_by:profile.id,archive_reason:reason}:row));form.reset();setNotice("Demande archivée distinctement de sa clôture.");setBusy(false);
  }

  async function reopenRequest(event:FormEvent<HTMLFormElement>,request:OperationalRequest){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const reason=String(new FormData(form).get("reason")||"").trim();const {error}=await supabase.rpc("reopen_request",{target_id:request.id,reason});
    if(error){showError(error.message);return;}setRequests(rows=>rows.map(row=>row.id===request.id?{...row,status:"under_review",archived_at:null,archived_by:null,archive_reason:null,reopened_count:(row.reopened_count||0)+1,last_reopened_at:new Date().toISOString(),last_reopened_by:profile.id}:row));setRequestEvents(rows=>[{id:crypto.randomUUID(),request_id:request.id,actor_id:profile.id,event_type:"reopened",body:reason,from_value:null,to_value:null,visibility:"requester",created_at:new Date().toISOString()},...rows]);form.reset();setNotice("Demande rouverte avec motif et traçabilité.");setBusy(false);
  }

  async function createBeneficiary(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);
    const payload={project_id:String(data.get("project_id")),full_name:String(data.get("full_name")||"").trim(),gender:String(data.get("gender")||"unknown"),birth_date:data.get("birth_date")||null,phone:String(data.get("phone")||"").trim()||null,locality:String(data.get("locality")||"").trim()||null,support_notes:String(data.get("support_notes")||"").trim()||null,consent_at:data.get("consent")?new Date().toISOString():null,assigned_to:String(data.get("assigned_to")||"")||null,created_by:profile.id};
    const {data:created,error}=await supabase.from("beneficiaries").insert(payload).select().single();
    if(error||!created){showError(error?.message||"Enregistrement impossible");return;}setBeneficiaries([created as BeneficiaryRow,...beneficiaries]);form.reset();setNotice("Bénéficiaire enregistré avec traçabilité du consentement.");setBusy(false);
  }

  async function uploadDocument(event:FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy(true);const form=event.currentTarget;const data=new FormData(form);const file=data.get("file");
    if(!(file instanceof File)||file.size===0){showError("Sélectionnez un fichier.");return;}if(file.size>15728640){showError("Le fichier dépasse la limite de 15 Mo.");return;}
    const safeName=file.name.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9._-]/g,"-");const objectPath=`${profile.id}/${crypto.randomUUID()}-${safeName}`;
    const upload=await supabase.storage.from("aiac-documents").upload(objectPath,file,{contentType:file.type,upsert:false});if(upload.error){showError(upload.error.message);return;}
    const payload={owner_id:profile.id,project_id:String(data.get("project_id")||"")||null,request_id:String(data.get("request_id")||"")||null,title:String(data.get("title")||file.name).trim(),file_url:objectPath,file_name:file.name,mime_type:file.type||null,size_bytes:file.size,visibility:String(data.get("visibility")||"private")};
    const {data:created,error}=await supabase.from("documents").insert(payload).select().single();if(error||!created){await supabase.storage.from("aiac-documents").remove([objectPath]);showError(error?.message||"Enregistrement impossible");return;}
    setDocuments([created as DocumentRow,...documents]);form.reset();setNotice("Document enregistré dans le coffre privé.");setBusy(false);
  }

  async function openDocument(document:DocumentRow){const {data,error}=await supabase.storage.from("aiac-documents").createSignedUrl(document.file_url,60,{download:document.file_name||document.title});if(error||!data){showError(error?.message||"Ouverture impossible");return;}window.open(data.signedUrl,"_blank","noopener,noreferrer");}

  const regions=Array.from(new Set([...requests.map(row=>row.region),...bodies.map(row=>row.region)].filter(Boolean) as string[])).sort();
  const firstResponseHours=requests.filter(row=>row.first_responded_at).map(row=>(new Date(row.first_responded_at!).getTime()-new Date(row.created_at).getTime())/3600000);
  const resolutionHours=requests.filter(row=>row.resolved_at||row.closed_at).map(row=>(new Date(row.resolved_at||row.closed_at!).getTime()-new Date(row.created_at).getTime())/3600000);
  const average=(values:number[])=>values.length?(values.reduce((sum,value)=>sum+value,0)/values.length).toFixed(1):"—";
  function timeline(events:WorkflowEvent[]){return <div className="eventTimeline"><h3>Historique</h3>{events.length?events.sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(event=><div className="eventItem" key={event.id}><b>{eventLabels[event.event_type]||event.event_type}{event.visibility==="internal"?" · INTERNE":""}</b>{event.body&&<p>{event.body}</p>}{!event.body&&<p>{event.from_value||"—"} → {event.to_value||"—"}</p>}<small>{event.actor_id?profileNames[event.actor_id]||"Utilisateur":"Système"} · {new Date(event.created_at).toLocaleString("fr-FR")}</small></div>):<p>Aucun événement enregistré.</p>}</div>;}

  return <section className="operationsWorkspace">
    {notice&&<div className="notice" role="status">{notice}<button onClick={()=>setNotice("")}>×</button></div>}
    <div className="operationNav">{[["pilotage","Pilotage"],["projets","Programmes → Projets → Activités"],["demandes","Demandes"],["taches","Tâches"],["beneficiaires","Bénéficiaires"],["documents","Documents"]].map(([id,label])=><button key={id} className={view===id?"active":""} onClick={()=>switchView(id)}>{label}</button>)}</div>

    {view==="pilotage"&&<><div className="statGrid operationStats"><article><b>{projects.filter(item=>item.status==="active").length}</b><span>Projets actifs</span></article><article><b>{tasks.filter(item=>!["done","cancelled"].includes(item.status)).length}</b><span>Tâches ouvertes</span></article><article><b>{requests.filter(item=>!["resolved","closed","rejected"].includes(item.status)).length}</b><span>Demandes à suivre</span></article><article><b>{beneficiaries.filter(item=>item.status==="active").length}</b><span>Bénéficiaires actifs</span></article></div><div className="portalPanel"><h2>Portefeuille opérationnel AIAC</h2><p>Projets, responsabilités, échéances et dossiers autorisés sont regroupés ici.</p>{tasks.filter(item=>item.status!=="done"&&item.due_at).sort((a,b)=>String(a.due_at).localeCompare(String(b.due_at))).slice(0,5).map(item=><div className="listRow" key={item.id}><div><b>{item.title}</b><small>{item.project_id?projectNames[item.project_id]:"Sans projet"} · {item.assigned_to?profileNames[item.assigned_to]:"Non affectée"}</small></div><span>{item.due_at?new Date(item.due_at).toLocaleDateString("fr-FR"):"—"}</span></div>)}</div></>}

    {view==="projets"&&<>
      <div className="portalPanel"><h2>Portefeuille hiérarchisé</h2><p>Créez dans l’ordre : <b>1. le programme</b>, <b>2. un projet rattaché</b>, puis <b>3. une activité dans ce projet</b>. Une activité hérite automatiquement du programme de son projet.</p></div>
      {isAdmin&&<div className="portalPanel"><h2>1 · Créer un programme</h2><form className="operationForm" onSubmit={createProgram}><input name="code" placeholder="Code du programme" maxLength={30} required/><input name="name" placeholder="Nom du programme" required/><input name="thematic_area" placeholder="Axe thématique"/><select name="manager_id"><option value="">Responsable à définir</option>{activeStaff.map(item=><option value={item.id} key={item.id}>{item.full_name||item.email}</option>)}</select><textarea name="description" placeholder="Objectifs et résultats attendus"/><label>Début<input name="start_date" type="date"/></label><label>Fin<input name="end_date" type="date"/></label><label>Budget (XAF)<input name="budget_amount" type="number" min="0" step="1"/></label><button disabled={busy}>Créer le programme</button></form></div>}
      {isAdmin&&<div className="portalPanel"><h2>2 · Créer un projet dans un programme</h2>{programs.length?<form className="operationForm" onSubmit={createProject}><select name="program_id" required><option value="">Programme parent obligatoire</option>{programs.filter(item=>!["completed","cancelled"].includes(item.status)).map(item=><option value={item.id} key={item.id}>{item.code} · {item.name}</option>)}</select><input name="code" placeholder="Code : AIAC-2026-01" minLength={2} maxLength={30} required/><input name="name" placeholder="Nom du projet" required/><textarea name="description" placeholder="Objectif et description"/><input name="location" placeholder="Zone d’intervention"/><label>Début<input name="start_date" type="date"/></label><label>Fin<input name="end_date" type="date"/></label><label>Budget prévisionnel (XAF)<input name="budget_amount" type="number" min="0" step="1"/></label><button disabled={busy}>Créer le projet</button></form>:<p>Créez d’abord un programme : aucun projet isolé ne peut être créé.</p>}</div>}
      <div className="portalPanel"><h2>3 · Créer une activité dans un projet</h2>{writableProjects.length?<form className="operationForm" onSubmit={createActivity}><select name="project_id" required><option value="">Projet parent obligatoire</option>{writableProjects.filter(item=>item.program_id).map(item=><option value={item.id} key={item.id}>{programNames[item.program_id||""]} → {item.code} · {item.name}</option>)}</select><input name="title" placeholder="Intitulé de l’activité" required/><select name="activity_type"><option value="meeting">Réunion</option><option value="training">Formation</option><option value="workshop">Atelier</option><option value="awareness">Sensibilisation</option><option value="field_visit">Visite terrain</option><option value="distribution">Distribution</option><option value="advocacy">Plaidoyer</option><option value="monitoring">Suivi-évaluation</option><option value="event">Événement</option><option value="other">Autre</option></select><textarea name="description" placeholder="Objectifs et déroulé"/><input name="location" placeholder="Lieu"/><label>Début<input name="starts_at" type="datetime-local" required/></label><label>Fin<input name="ends_at" type="datetime-local"/></label><input name="expected_participants" type="number" min="0" placeholder="Participants attendus"/><input name="budget_amount" type="number" min="0" placeholder="Budget XAF"/><select name="manager_id"><option value="">Moi-même</option>{activeStaff.map(item=><option value={item.id} key={item.id}>{item.full_name||item.email}</option>)}</select><button disabled={busy}>Créer l’activité</button></form>:<p>Créez d’abord un projet, ou demandez à être ajouté à son équipe.</p>}</div>
      <div className="portalPanel"><h2>Programmes, projets et activités</h2>{programs.length?programs.map(program=>{const children=projects.filter(project=>project.program_id===program.id);return <details className="workflowCard" key={program.id} open><summary><span><b>{program.code} · {program.name}</b><small>{program.thematic_area||"Axe à définir"} · {children.length} projet(s)</small></span><span className={`operationBadge ${program.status}`}>{projectStatus[program.status]||program.status}</span></summary><div className="workflowBody">{program.description&&<p>{program.description}</p>}{children.length?children.map(project=>{const projectActivities=activities.filter(activity=>activity.project_id===project.id);return <details className="workflowCard" key={project.id}><summary><span><b>{project.code} · {project.name}</b><small>{project.location||"Zone à définir"} · {projectActivities.length} activité(s)</small></span><span className={`operationBadge ${project.status}`}>{projectStatus[project.status]||project.status}</span></summary><div className="workflowBody">{project.description&&<p>{project.description}</p>}{projectActivities.length?projectActivities.map(activity=><div className="listRow" key={activity.id}><div><b>{activity.code} · {activity.title}</b><small>{activity.location||"Lieu à définir"} · {new Date(activity.starts_at).toLocaleString("fr-FR")}</small></div><span className={`operationBadge ${activity.status}`}>{activityStatus[activity.status]||activity.status}</span></div>):<p>Aucune activité dans ce projet.</p>}</div></details>}):<p>Aucun projet dans ce programme.</p>}</div></details>}):<p>Aucun programme n’a encore été créé.</p>}</div>
      {manageableProjects.length>0&&<div className="portalPanel"><h2>Composer une équipe de projet</h2><form className="operationForm compact" onSubmit={addMember}><select name="project_id" required><option value="">Projet</option>{manageableProjects.map(item=><option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select><select name="user_id" required><option value="">Collaborateur</option>{activeCollaborators.filter(item=>item.id!==profile.id).map(item=><option key={item.id} value={item.id}>{item.full_name||item.email}</option>)}</select><select name="member_role"><option value="lead">Responsable</option><option value="officer">Agent</option><option value="contributor">Contributeur</option><option value="viewer">Observateur</option></select><button disabled={busy}>Ajouter</button></form>{members.map(member=><div className="listRow" key={`${member.project_id}-${member.user_id}`}><div><b>{profileNames[member.user_id]||member.user_id}</b><small>{projectNames[member.project_id]||member.project_id}</small></div><span>{member.member_role}</span></div>)}</div>}
    </>}

    {view==="demandes"&&<>
      <div className="statGrid operationStats"><article><b>{average(firstResponseHours)} h</b><span>Délai moyen de première réponse</span></article><article><b>{average(resolutionHours)} h</b><span>Délai moyen de résolution</span></article><article><b>{requests.filter(row=>row.due_at&&!row.archived_at&&new Date(row.due_at)<new Date()&&!['resolved','closed','rejected'].includes(row.status)).length}</b><span>Échéances dépassées</span></article><article><b>{interventions.length}</b><span>Dossiers d’intervention</span></article></div>
      <div className="portalPanel"><h2>Traitement complet des demandes</h2><div className="requestAdvancedFilters"><select value={requestRegion} onChange={event=>{setRequestRegion(event.target.value);setPage(1);}}><option value="all">Toutes les régions</option>{regions.map(value=><option value={value} key={value}>{value}</option>)}</select><label>Du<input type="date" value={requestFrom} onChange={event=>{setRequestFrom(event.target.value);setPage(1);}}/></label><label>Au<input type="date" value={requestTo} onChange={event=>{setRequestTo(event.target.value);setPage(1);}}/></label><select value={archiveFilter} onChange={event=>{setArchiveFilter(event.target.value);setPage(1);}}><option value="active">Non archivées</option><option value="archived">Archivées</option><option value="all">Toutes</option></select></div>{toolbar(filteredRequests,requestStatus,()=>exportCsv("demandes-aiac.csv",["Objet","Type","État","Priorité","Responsable","Projet","Organe","Région","Échéance","Première réponse","Résolution","Archivage"],filteredRequests.map(item=>[item.subject,item.request_type,requestStatus[item.status],priorities[item.priority],profileNames[item.assigned_to||""],projectNames[item.project_id||""],bodyNames[item.body_id||""],item.region,item.due_at,item.first_responded_at,item.resolved_at||item.closed_at,item.archived_at])),"Objet, description, type, organe, région ou projet")}
      {paginate(filteredRequests,page).items.map(request=>{const canManage=isAdmin||(request.project_id?managedProjectIds.has(request.project_id):false)||request.assigned_to===profile.id;const existingIntervention=interventions.find(row=>row.request_id===request.id);return <details className="workflowCard" key={request.id}><summary><span><b>{request.subject}</b><small>{request.request_type} · {new Date(request.created_at).toLocaleDateString("fr-FR")} · {bodyNames[request.body_id||""]||"Structure non définie"} · {request.region||"Région non définie"}</small></span><span className={`operationBadge ${request.status}`}>{request.archived_at?"Archivée":requestStatus[request.status]}</span></summary><div className="workflowBody"><p>{request.description}</p><div className="requestMetrics"><span>Première réponse : {request.first_responded_at?new Date(request.first_responded_at).toLocaleString("fr-FR"):"en attente"}</span><span>Résolution : {request.resolved_at||request.closed_at?new Date(request.resolved_at||request.closed_at!).toLocaleString("fr-FR"):"en cours"}</span><span>Réouvertures : {request.reopened_count||0}</span>{existingIntervention&&<span>Dossier : {existingIntervention.case_number}</span>}</div>
        <form className="workflowEdit" onSubmit={event=>updateRequest(event,request)}><label>État<select name="status" defaultValue={request.status} disabled={!canManage}>{Object.entries(requestStatus).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>Priorité<select name="priority" defaultValue={request.priority} disabled={!canManage}>{Object.entries(priorities).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>Responsable<select name="assigned_to" defaultValue={request.assigned_to||""} disabled={!canManage}><option value="">Non affectée</option>{activeStaff.map(item=><option value={item.id} key={item.id}>{item.full_name||item.email}</option>)}</select></label><label>Projet<select name="project_id" defaultValue={request.project_id||""} disabled={!canManage}><option value="">Sans projet</option>{projects.map(item=><option value={item.id} key={item.id}>{item.code} · {item.name}</option>)}</select></label><label>Organe / service / coordination / antenne<select name="body_id" defaultValue={request.body_id||""} disabled={!canManage}><option value="">Non rattachée</option>{bodies.filter(row=>row.status==="active").map(row=><option value={row.id} key={row.id}>{row.code} · {row.name}</option>)}</select></label><label>Région<input name="region" defaultValue={request.region||""} disabled={!canManage}/></label><label>Échéance<input name="due_at" type="datetime-local" defaultValue={request.due_at?new Date(request.due_at).toISOString().slice(0,16):""} disabled={!canManage}/></label><button disabled={busy||!canManage}>Enregistrer</button></form>
        <div className="institutionalSplit"><form className="commentForm" onSubmit={event=>addComment(event,"request",request.id)}><select name="visibility" defaultValue="internal"><option value="internal">Note interne — invisible au demandeur</option><option value="requester">Réponse visible au demandeur</option></select><textarea name="body" minLength={1} maxLength={5000} placeholder="Commentaire ou note de traitement" required/><button disabled={busy||!canManage}>Ajouter</button></form><form className="commentForm" onSubmit={event=>requestInformation(event,request)}><textarea name="message" minLength={5} maxLength={5000} placeholder="Informations complémentaires attendues" required/><label>Réponse souhaitée avant<input name="response_due_at" type="datetime-local"/></label><button disabled={busy||!canManage}>Demander des informations</button></form></div>
        {!existingIntervention&&<form className="operationForm compact" onSubmit={event=>convertToIntervention(event,request)}><h3 className="wideField">Convertir en dossier d’intervention</h3><select name="body_id" defaultValue={request.body_id||""}><option value="">Organe responsable</option>{bodies.filter(row=>row.status==="active").map(row=><option value={row.id} key={row.id}>{row.code} · {row.name}</option>)}</select><select name="project_id" defaultValue={request.project_id||""}><option value="">Sans projet</option>{projects.map(row=><option value={row.id} key={row.id}>{row.code} · {row.name}</option>)}</select><select name="assigned_to" defaultValue={request.assigned_to||""}><option value="">Agent à affecter</option>{activeStaff.map(row=><option value={row.id} key={row.id}>{row.full_name||row.email}</option>)}</select><input name="region" defaultValue={request.region||""} placeholder="Région"/><select name="sensitivity"><option value="standard">Standard</option><option value="confidential">Confidentiel</option><option value="restricted">Restreint</option><option value="vbg">VBG</option><option value="medical">Médical</option><option value="psychosocial">Psychosocial</option><option value="whistleblowing">Signalement interne</option></select><label>Échéance<input name="due_at" type="datetime-local" defaultValue={request.due_at?new Date(request.due_at).toISOString().slice(0,16):""}/></label><button disabled={busy||!canManage}>Créer le dossier</button></form>}
        {(['resolved','closed','rejected'].includes(request.status)||request.archived_at)&&<div className="institutionalSplit">{!request.archived_at&&<form className="commentForm" onSubmit={event=>archiveRequest(event,request)}><input name="reason" minLength={5} placeholder="Motif d’archivage" required/><button disabled={busy||!canManage}>Archiver</button></form>}<form className="commentForm" onSubmit={event=>reopenRequest(event,request)}><input name="reason" minLength={5} placeholder="Motif de réouverture" required/><button disabled={busy||!canManage}>Rouvrir officiellement</button></form></div>}
        {timeline(requestEvents.filter(item=>item.request_id===request.id))}</div></details>;})}</div>
    </>}

    {view==="taches"&&<><div className="portalPanel"><h2>Nouvelle tâche</h2>{writableProjects.length?<form className="operationForm compact" onSubmit={createTask}><input name="title" placeholder="Intitulé de la tâche" required/><textarea name="description" placeholder="Consignes"/><select name="project_id" required><option value="">Projet</option>{writableProjects.map(item=><option value={item.id} key={item.id}>{item.code} · {item.name}</option>)}</select><select name="request_id"><option value="">Aucune demande liée</option>{requests.map(item=><option value={item.id} key={item.id}>{item.subject}</option>)}</select><select name="assigned_to"><option value="">Non affectée</option>{activeStaff.map(item=><option value={item.id} key={item.id}>{item.full_name||item.email}</option>)}</select><select name="priority" defaultValue="normal">{Object.entries(priorities).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select><label>Échéance<input name="due_at" type="datetime-local"/></label><button disabled={busy}>Créer</button></form>:<p>Vous disposez d’un accès en lecture seule aux projets visibles.</p>}</div><div className="portalPanel"><h2>Plan de travail</h2>{toolbar(filteredTasks,taskStatus,()=>exportCsv("taches-aiac.csv",["Tâche","État","Priorité","Responsable","Projet","Échéance"],filteredTasks.map(item=>[item.title,taskStatus[item.status],priorities[item.priority],profileNames[item.assigned_to||""],projectNames[item.project_id||""],item.due_at])),"Tâche, consigne, projet ou responsable")}{paginate(filteredTasks,page).items.map(task=>{const canManage=isAdmin||(task.project_id?managedProjectIds.has(task.project_id):false);const canUpdate=canManage||task.assigned_to===profile.id;return <details className="workflowCard" key={task.id}><summary><span><b>{task.title}</b><small>{task.project_id?projectNames[task.project_id]:"Sans projet"} · {task.assigned_to?profileNames[task.assigned_to]:"Non affectée"}</small></span><span className={`operationBadge ${task.status}`}>{taskStatus[task.status]}</span></summary><div className="workflowBody"><form className="workflowEdit" onSubmit={event=>updateTask(event,task,canManage)}><label>Intitulé<input name="title" defaultValue={task.title} disabled={!canManage}/></label><label className="wideField">Consignes<textarea name="description" defaultValue={task.description||""} disabled={!canManage}/></label><label>État<select name="status" defaultValue={task.status} disabled={!canUpdate}>{Object.entries(taskStatus).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>Priorité<select name="priority" defaultValue={task.priority} disabled={!canManage}>{Object.entries(priorities).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><label>Responsable<select name="assigned_to" defaultValue={task.assigned_to||""} disabled={!canManage}><option value="">Non affectée</option>{activeStaff.map(item=><option value={item.id} key={item.id}>{item.full_name||item.email}</option>)}</select></label><label>Projet<select name="project_id" defaultValue={task.project_id||""} disabled={!canManage}>{projects.map(item=><option value={item.id} key={item.id}>{item.code}</option>)}</select></label><label>Demande<select name="request_id" defaultValue={task.request_id||""} disabled={!canManage}><option value="">Aucune</option>{requests.map(item=><option value={item.id} key={item.id}>{item.subject}</option>)}</select></label><label>Échéance<input name="due_at" type="datetime-local" defaultValue={task.due_at?new Date(task.due_at).toISOString().slice(0,16):""} disabled={!canManage}/></label><button disabled={busy||!canUpdate}>Enregistrer</button></form><form className="commentForm" onSubmit={event=>addComment(event,"task",task.id)}><textarea name="body" maxLength={5000} placeholder="Compte rendu, blocage ou commentaire" required/><button disabled={busy}>Commenter</button></form>{timeline(taskEvents.filter(item=>item.task_id===task.id))}</div></details>;})}</div></>}

    {view==="beneficiaires"&&<><div className="portalPanel"><h2>Enregistrer un bénéficiaire</h2>{manageableProjects.length>0?<form className="operationForm" onSubmit={createBeneficiary}><select name="project_id" required><option value="">Projet concerné</option>{manageableProjects.map(item=><option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select><input name="full_name" placeholder="Nom complet" required/><select name="gender" defaultValue="unknown"><option value="unknown">Genre non renseigné</option><option value="female">Femme</option><option value="male">Homme</option><option value="other">Autre</option><option value="prefer_not_to_say">Préfère ne pas répondre</option></select><label>Date de naissance<input name="birth_date" type="date"/></label><input name="phone" placeholder="Téléphone"/><input name="locality" placeholder="Localité"/><select name="assigned_to"><option value="">Agent responsable</option>{activeStaff.map(item=><option key={item.id} value={item.id}>{item.full_name||item.email}</option>)}</select><textarea name="support_notes" placeholder="Appui prévu — données strictement nécessaires" maxLength={5000}/><label className="consentCheck"><input name="consent" type="checkbox" required/> Consentement obtenu et enregistré</label><button disabled={busy}>Enregistrer</button></form>:<p>Seuls les responsables autorisés peuvent créer un dossier bénéficiaire.</p>}</div><div className="portalPanel"><h2>Registre autorisé</h2>{toolbar(filteredBeneficiaries,{active:"Actif",inactive:"Inactif",closed:"Clôturé"},()=>exportCsv("beneficiaires-aiac.csv",["Référence","Nom","Projet","Localité","Statut","Responsable"],filteredBeneficiaries.map(item=>[item.reference_code,item.full_name,projectNames[item.project_id],item.locality,item.status,profileNames[item.assigned_to||""]])),"Référence, nom, localité ou projet")}{paginate(filteredBeneficiaries,page).items.map(item=><div className="listRow beneficiaryRow" key={item.id}><div><b>{item.full_name}</b><small>{item.reference_code} · {projectNames[item.project_id]} · {item.locality||"Localité non renseignée"}</small></div><span>{item.status}</span></div>)}</div></>}

    {view==="documents"&&<><div className="portalPanel"><h2>Déposer un document</h2><form className="operationForm" onSubmit={uploadDocument}><input name="title" placeholder="Titre du document" required/><select name="project_id"><option value="">Document personnel</option>{writableProjects.map(item=><option value={item.id} key={item.id}>{item.code} · {item.name}</option>)}</select><select name="request_id"><option value="">Aucune demande liée</option>{requests.map(item=><option value={item.id} key={item.id}>{item.subject}</option>)}</select><select name="visibility" defaultValue="private"><option value="private">Privé — propriétaire et administrateurs</option><option value="staff">Équipe du projet</option><option value="request">Demandeur et équipe autorisée</option></select><input name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png" required/><small>PDF, Word, Excel, JPG ou PNG — 15 Mo maximum.</small><button disabled={busy}>Déposer dans le coffre</button></form></div><div className="portalPanel"><h2>Coffre documentaire</h2>{toolbar(filteredDocuments,{private:"Privé",staff:"Équipe",request:"Demande"},()=>exportCsv("documents-aiac.csv",["Titre","Fichier","Projet","Visibilité","Type","Taille (octets)","Créé le"],filteredDocuments.map(item=>[item.title,item.file_name,projectNames[item.project_id||""],item.visibility,item.mime_type,item.size_bytes,item.created_at])),"Titre, fichier, projet ou type")}{paginate(filteredDocuments,page).items.map(document=><div className="listRow documentRow" key={document.id}><div><b>{document.title}</b><small>{document.file_name||"Fichier"} · {document.project_id?projectNames[document.project_id]:"Personnel"} · {document.size_bytes?`${(document.size_bytes/1024/1024).toFixed(2)} Mo`:"Taille inconnue"}</small></div><button onClick={()=>openDocument(document)}>Ouvrir 60 s</button></div>)}</div></>}
  </section>;
}
